REPLACE INTO `book` VALUES (1,'AI 微短剧制作实战营','星链科技','1','清远星链科技',199.00,'2026-08-01',9,'0','0','',NULL,NULL,'9787536692930','[b]AI 微短剧全流程制作[/b]：剧本生成、AI 视频生成、数字人出镜、剪辑调色到平台投放，[quote]一个人 + AI = 一条微短剧生产线[/quote]2026 年一季度上新微短剧中 AI 制作占比已超 [color=#c65d43]95%[/color]，[url=#]了解行业报告 →[/url]',NULL,'admin','2026-06-15 10:00:00','',NULL),(2,'超级数字人实操课','塔链人工智能科技','1','塔链科技',99.00,'2026-07-15',3,'0','0','',NULL,NULL,'9787111544937','本土自研数字人平台实操：形象定制、语音克隆、直播带货、短视频口播全场景落地。名额紧张，手慢无。',NULL,'admin','2026-06-15 10:00:00','',NULL),(3,'共享工位月租计划','数智游民创新工场','3','天安智谷产业园',500.00,'2026-06-01',20,'1','0','',NULL,NULL,'9787505732534','（已满租）B 类付费入驻：小额租金 + 分摊水电网络费，工位注册 / 地址挂靠一站解决。下一批工位开放敬请关注。',NULL,'admin','2026-06-15 10:00:00','',NULL),(4,'AI 短视频代运营服务','正经点赞（清远）媒体科技','1','正经点赞',0.00,'2026-07-20',50,'0','0','',NULL,NULL,'9787506365437','免费体验：文旅推广、政务科普、城市形象类 AI 短视频全链路代运营，订单由社区统一对接分发。',NULL,'admin','2026-06-15 10:00:00','',NULL),(6,'一人公司法律咨询包','李律师团队','2','广东观澜律师事务所',299.00,'2026-07-10',8,'0','0','',NULL,NULL,'9787544253994','OPC 专属：一人公司注册、股权架构、合同审查、合规咨询一站式服务包。',NULL,'admin','2026-06-15 10:00:00','',NULL),(7,'数字游民共居空间','清远青年社区','3','碧桂园清远',800.00,'2026-07-25',2,'0','0','',NULL,NULL,'9787020029532','共居 + 共创：按月租入住共居空间，含共享工位与社区活动，适合数字游民长期扎根清远。',NULL,'admin','2026-06-15 10:00:00','',NULL),(8,'AIGC 内容创作营','正经点赞（清远）媒体科技','1','正经点赞',149.00,'2026-08-19',30,'0','0','',NULL,NULL,'9787530216781','新服务：AIGC 图文/视频/多平台内容生产实训，从创意到商业化的完整链路。',NULL,'admin','2026-08-21 09:12:06','',NULL),(9,'一人公司财税合规指南','王会计工作室','2','清远税务学会',0.00,'2026-06-28',25,'0','0','',NULL,NULL,'9787020002207','OPC 必学：一人公司企业所得税/分红个税/年度审计要求，与个体户税负对比，财税小白听得懂。',NULL,'admin','2026-07-01 10:00:00','',NULL),(10,'AI 获客系统实战营','星火深智','2','星火深智',169.00,'2026-07-08',28,'0','0','',NULL,NULL,'9787020008735','本土自研 AI 获客系统：线索挖掘、智能触达、客户培育全流程自动化，一人公司获客不再难。',NULL,'admin','2026-07-01 10:00:00','',NULL),(11,'GEO 生成式引擎优化课','清远 AI 实验室','2','清远 AI 实验室',169.00,'2026-07-12',26,'0','0','',NULL,NULL,'9787020008728','GEO（Generative Engine Optimization）：让你的品牌与产品在大模型回答中被优先推荐。',NULL,'admin','2026-07-01 10:00:00','',NULL),(12,'数字游民保险方案咨询','平安保险清远','3','中国平安',0.00,'2026-07-05',24,'0','0','',NULL,NULL,'9787020008759','灵活就业社保、补充商业险、意外险——数字游民与一人公司主理人的保障方案一对一咨询。',NULL,'admin','2026-07-01 10:00:00','',NULL),(13,'AI 短视频运营训练营','孙悦','1','抖音生活服务',88.00,'2026-06-20',40,'0','0','',NULL,NULL,'9787020042494','爆款选题、AI 图文生成、笔记优化、涨粉变现全链路，往期学员 200+。',NULL,'admin','2026-07-01 10:00:00','',NULL),(14,'视频号 AI 剪辑速成','周涛','1','微信视频号',0.00,'2026-07-18',35,'0','0','',NULL,NULL,'9787532748662','剪映 + AI 工具快速出片：从素材管理到成片发布，一天学会日更节奏。',NULL,'admin','2026-07-01 10:00:00','',NULL),(15,'具身智能训练场开放日','数智游民创新工场','3','天安智谷产业园',0.00,'2026-06-15',0,'0','0','',NULL,NULL,'9787544270878','（满员可候补）具身智能训练场开放日：机器人调试、场景演练、行业交流，名额释放自动通知。',NULL,'admin','2026-07-01 10:00:00','',NULL),(16,'AI 生活场景训练场体验','数智游民创新工场','3','天安智谷产业园',0.00,'2026-08-18',0,'0','0','',NULL,NULL,'9787544270879','新服务：AI 生活场景训练场体验——智能家居、AI 陪伴、健康监测场景演示与试用。',NULL,'admin','2026-08-21 09:12:06','',NULL),(17,'AI 工牌场景试用','数智游民创新工场','3','星链科技',0.00,'2026-07-22',30,'0','0','',NULL,NULL,'9787020008742','AI 工牌：会议纪要与客户画像自动生成，一人公司商务场景提效神器，限时免费试用。',NULL,'admin','2026-07-01 10:00:00','',NULL),(18,'AI 绘画与设计基础','光年制造工作室','2','光年制造',0.00,'2026-06-18',32,'0','0','',NULL,NULL,'9787537812249','Midjourney / Stable Diffusion 入门：从提示词到商业级出图的工作流，本土设计工作室带练。',NULL,'admin','2026-07-01 10:00:00','',NULL),(19,'AI 眼镜体验与评测','数智游民创新工场','3','天安智谷产业园',0.00,'2026-07-28',27,'0','0','',NULL,NULL,'9787020009626','AI 眼镜实机体验与评测：第一视角 AI 助手、实时翻译、拍照识物，长生态链硬件尝鲜。',NULL,'admin','2026-07-01 10:00:00','',NULL),(20,'OPC 创客训练营','星链科技','2','清远星链科技',0.00,'2026-07-30',2,'0','0','',NULL,NULL,'9787121022982','名额紧张：社区王牌训练营（已举办多期）——一人公司从 0 到 1：注册、税务、AI 工具矩阵、获客、订单全流程。',NULL,'admin','2026-07-01 10:00:00','',NULL),(21,'AI 应用开发与微调课','塔链人工智能科技','2','塔链科技',128.00,'2026-08-05',10,'0','0','',NULL,NULL,'9787111407010','开源模型私有化部署与微调实战（70B 以内一体机可用），数据不出域，一人公司也能玩转模型。',NULL,'admin','2026-07-01 10:00:00','',NULL),(22,'毕业生 AI 实训营','北江人工智能产教融合研究院','2','北江产教融合研究院',0.00,'2026-08-20',20,'0','0','',NULL,NULL,'9787101054033','新服务：面向本地高校毕业生与清远籍大学生的免费 OPC 创业实训营，结营对接社区订单。',NULL,'admin','2026-08-21 09:12:06','',NULL),(23,'创客大赛报名','数智游民创新工场','2','清远星谷科技园',0.00,'2026-08-01',98,'0','0','',NULL,NULL,'9780026082402','首届人工智能 OPC 创客短视频创作大赛报名通道：报名即参赛，社区设立创客基金，联动头部 AI 企业对接全国稳定内容订单。',NULL,'admin','2026-08-24 11:13:52','',NULL);
