REPLACE INTO `cms_block` VALUES (1,'home-intro','home',NULL,'一个人 + AI，把想法变成事业——免费工位 · 算力加持 · 订单牵引，拎脑入驻清远 AI 生态社区','数智游民创新工场由清城区政府与清远星链科技合作共建，以\"国企引领、民企赋能\"模式运营，从签约到揭牌仅用 21 天。社区为 AI 时代的超级个体与一人公司提供\"拎脑入驻\"的完整生态：免费工位与注册代办降低启动门槛，70B 大模型一体机与算力券让 AI 生产力触手可及，文创订单对接与创客基金让作品直接变现，省职教城 14 万人才与高校实践基地持续注入新鲜血液。',NULL,NULL,1,'1',2,'admin','2026-08-27 08:14:26','',NULL),(2,'home-concept','home','品牌理念',NULL,NULL,NULL,NULL,2,'0',6,'admin','2026-08-27 09:34:32','cards','{\"cols\": 2, \"cards\": [{\"icon\": \"🏢\", \"text\": \"一人公司（One Person Company）不只是法律意义上的企业形态，更是 AI 时代的\\\"生产力引擎\\\"：以最低合规成本注册经营主体，再以 AI 深度协同放大个人产出，实现\\\"单人成军\\\"的轻量化创业——一个人，就是一家公司。\", \"title\": \"OPC 新内涵\"}, {\"icon\": \"💻\", \"text\": \"不依赖场地、不依赖团队规模，一台高性能 AI 电脑即可创业。内容创作、技术开发、创意设计……只要有创意与 AI 工具，就能承接订单、把想法变成事业。社区提供工位、算力与订单，让游民安心扎根。\", \"title\": \"什么是\\\"数智游民\\\"\"}], \"steps\": [{\"desc\": \"社区提供注册代办与绿色通道，一人一公司轻松落地\", \"title\": \"注册 OPC 一人公司\"}, {\"desc\": \"大模型平台 / 70B 一体机 / 算力券，工具链一步到位\", \"title\": \"搭建 AI 工具矩阵\"}, {\"desc\": \"文创订单 / 创客基金 / 大赛，以订单牵引创业起步\", \"title\": \"承接订单变现\"}], \"subtitle\": \"\"}'),(3,'home-feature-1','home',NULL,NULL,NULL,NULL,NULL,3,'1',1,'admin','2026-08-27 08:14:26','',NULL),(4,'home-feature-2','home',NULL,NULL,NULL,NULL,NULL,4,'1',1,'admin','2026-08-27 08:14:26','',NULL),(5,'home-feature-3','home',NULL,NULL,NULL,NULL,NULL,5,'1',1,'admin','2026-08-27 08:14:26','',NULL),(6,'home-ecosystem','home','产业生态',NULL,NULL,NULL,NULL,5,'0',4,'admin','2026-08-27 08:14:26','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"🎬\", \"text\": \"AI 微短剧、超级数字人、AIGC 内容创作——2026 年一季度上新微短剧中 AI 制作占比已超 95%，内容创作全面进入\\\"一人成军\\\"时代。社区提供制作实战营与订单对接，让创作直接变成收入。\", \"title\": \"AI 内容创作\"}, {\"icon\": \"⚙️\", \"text\": \"AI 获客系统、GEO（生成式引擎优化）、AI 应用开发——以 AI 工具重构获客与交付流程，让个人与小微企业也能用上企业级 AI 能力。技术赋能 + 场景落地，AI 不再是概念而是生产力。\", \"title\": \"AI 技术应用\"}, {\"icon\": \"🤖\", \"text\": \"AI 眼镜、AI 手机、AI 工牌、AI 玩具、AI 陪伴、AI 外骨骼辅助装置，以及具身智能训练场、工业/生活场景训练场——从硬件长生态链到真实落地场景，OPC 生态正在向万物智能延伸。\", \"title\": \"AI 硬件与场景\"}]}'),(7,'about-hero-sub','about',NULL,'','清远市首个人工智能 OPC（一人公司）生态社区 —— 让\"一个人 + AI\"也能轻松创业',NULL,NULL,1,'0',4,'admin','2026-08-27 08:14:26','',NULL),(8,'about-cta','about',NULL,NULL,NULL,NULL,NULL,2,'1',1,'admin','2026-08-27 08:14:26','',NULL),(9,'join-hero-sub','join',NULL,NULL,NULL,NULL,NULL,1,'0',1,'admin','2026-08-27 08:14:26','',NULL),(10,'talent-hero-sub','talent',NULL,NULL,NULL,NULL,NULL,1,'0',1,'admin','2026-08-27 08:14:26','',NULL),(11,'talent-cta','talent',NULL,NULL,NULL,NULL,NULL,2,'1',1,'admin','2026-08-27 08:14:26','',NULL),(12,'industry-hero-sub','industry',NULL,NULL,NULL,NULL,NULL,1,'0',1,'admin','2026-08-27 08:14:26','',NULL),(13,'industry-cta','industry',NULL,NULL,NULL,NULL,NULL,2,'1',1,'admin','2026-08-27 08:14:26','',NULL),(14,'about-loc','about','📍 社区定位',NULL,NULL,NULL,NULL,1,'0',2,'admin','2026-08-27 09:15:42','cards','{\"cols\": 2, \"cards\": [{\"icon\": \"🏢\", \"text\": \"一人公司（One Person Company）不只是法律意义上的\\\"一人公司\\\"载体，更是 AI 时代的\\\"生产力引擎\\\"——以最低合规成本注册经营主体，再以 AI 深度协同放大个人产出。\", \"title\": \"OPC 新内涵\"}, {\"icon\": \"🧑‍💻\", \"text\": \"\\\"数智游民\\\"= 一个人 + 一台高性能 AI 电脑即可创业：不依赖场地、不依赖团队规模，只要有创意与 AI 工具，就能承接内容创作、技术开发、创意设计等订单。\", \"title\": \"什么是\\\"数智游民\\\"\"}], \"subtitle\": \"\"}'),(15,'about-coop','about','🤝 合作模式：\"国企引领、民企赋能\"',NULL,NULL,NULL,NULL,3,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"🏛️\", \"text\": \"提供场地、硬件、后勤保障与本地资源，为创业者托底基础设施，让创业者拎包入驻、轻装上阵。\", \"title\": \"政府方 · 区属国企顺拓集团\"}, {\"icon\": \"🚀\", \"text\": \"负责课程搭建、师资组建、订单对接、工位招商，把 AI 课程体系、产业订单与运营能力带进社区。\", \"title\": \"企业方 · 清远星链科技\"}, {\"icon\": \"🤝\", \"text\": \"双方合资组建星拓公司负责社区日常运营，\\\"国企引领、民企赋能\\\"，充分发挥国资资源与民企活力的双重优势。\", \"title\": \"合资运营 · 星拓公司\"}], \"subtitle\": \"清城区政府 × 清远市星链科技有限公司 合作共建清城区人工智能 OPC 生态社区，双方优势互补、共建共享。\"}'),(16,'about-location','about','🏞️ 区位优势',NULL,NULL,NULL,NULL,2,'0',2,'admin','2026-08-27 09:13:42','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"📍\", \"text\": \"<p>清城区是清远市中心城区，城市配套成熟、交通便利，是承接 AI 创业与数字游民落地的主阵地。</p>\", \"title\": \"中心城区区位\"}, {\"icon\": \"🎭\", \"text\": \"<p>丰厚的文旅资源为 AI 内容创作提供天然素材；省职教城约 14 万师生，构建起庞大的人才蓄水池。</p>\", \"title\": \"文旅资源与人才储备\"}, {\"icon\": \"📊\", \"text\": \"多元产业应用场景与广阔内需市场，为 AI 应用落地与订单对接提供真实场景与稳定需求。\", \"title\": \"产业场景与内需市场\"}], \"subtitle\": \"\"}'),(17,'about-milestones','about','📅 发展历程',NULL,NULL,NULL,NULL,4,'0',1,'admin','2026-08-26 08:15:53','timeline','{\"items\": [{\"date\": \"2026-04-29\", \"desc\": \"数智游民创新工场（清远）科技有限公司注册成立（注册资本 100 万元）。\", \"title\": \"运营公司成立\"}, {\"date\": \"2026-07-11\", \"desc\": \"清城区政府与清远市星链科技有限公司签署合作框架协议，共建人工智能 OPC 生态社区。\", \"title\": \"签署合作框架协议\"}, {\"date\": \"2026-08-01\", \"desc\": \"揭牌仪式在清远星谷科技园举行。从签约到揭牌仅 21 天，跑出\\\"清城速度\\\"。\", \"title\": \"正式揭牌运营\"}]}'),(18,'about-operator','about','🏭 运营主体',NULL,NULL,NULL,NULL,5,'0',1,'admin','2026-08-26 08:15:53','text','{\"text\": \"<b>数智游民创新工场（清远）科技有限公司</b>：2026-04-29 成立，注册资本 100 万元，负责清城区人工智能 OPC 生态社区的日常运营与入驻招商服务。\"}'),(19,'about-legal','about','⚖️ OPC 的法律与税务',NULL,NULL,NULL,NULL,6,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"🛡️\", \"text\": \"<b>有限责任</b>：股东仅以出资额为限对公司债务承担责任，个人房产、存款等家庭财产受法律保护；<b>独立法人地位</b>：商业合作中比个体户更具公信力；<b>决策高效</b>：内部治理结构简单，能快速响应市场。\", \"title\": \"法律优势\"}, {\"icon\": \"📋\", \"text\": \"<b>举证责任倒置</b>：一旦涉诉，股东需自己证明公司财产独立于个人财产，否则承担连带责任；<b>一人一公司</b>：一个自然人只能投资设立一家一人有限责任公司；<b>强制审计</b>：每年度终了须编制财务会计报告并依法审计。\", \"title\": \"法律边界\"}, {\"icon\": \"🧾\", \"text\": \"OPC 需缴纳<b>企业所得税</b>（一般 25%，小微企业有优惠）加<b>个人所得税</b>（分红时缴 20%）；相比个体户 5%-35% 超额累进税率存在\\\"双重征税\\\"，但利润做大后综合税负可能更有优势。社区提供注册代办与纳税申报服务。\", \"title\": \"税务结构\"}]}'),(20,'about-cta-banner','about','想成为社区一员？',NULL,NULL,NULL,NULL,7,'0',1,'admin','2026-08-26 08:15:53','cta','{\"text\": \"免费工位、政策赋能、订单对接，一个人 + AI 即刻启程 ｜ 咨询电话：0763-3391888\", \"btnLink\": \"join.html\", \"btnText\": \"前往入驻招商\"}'),(21,'join-ways','join','🏠 两种入驻方式',NULL,NULL,NULL,NULL,1,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 2, \"cards\": [{\"icon\": \"🌟\", \"text\": \"<b>条件：</b>获得社区老板认可<br><b>合伙人权益：</b><ul><li>房租、水电、高速宽带全免</li><li>注册代办、纳税申报服务</li><li>本地 Token 免费使用</li><li>可申请试用 70B 以内大模型一体机</li><li>超高规格办公装修</li><li>多间高规格会议室</li><li>工会和党建公共空间</li></ul>\", \"title\": \"A 类：免费入驻 · 成为 OPC 合伙人\"}, {\"icon\": \"🪑\", \"text\": \"<b>适用：</b>暂未获社区认可、或不愿受股权约束的创业者<br><b>费用：</b>支付小额租金，分摊水电网络费<br><b>成员权益：</b><ul><li>共享社区工位与高速网络</li><li>使用公共会议室与公共空间</li><li>参与社区课程、赛事与订单对接</li><li>可随时申请转为 OPC 合伙人</li></ul>\", \"title\": \"B 类：付费入驻 · 普通成员\"}]}'),(22,'join-companies','join','🏢 首批入驻企业（简列）',NULL,NULL,NULL,NULL,2,'0',1,'admin','2026-08-26 08:15:53','text','{\"text\": \"塔链人工智能科技（广州）有限公司 · AI 技术研发 ｜ 南京世东智脑人工智能有限公司 · AI 技术研发 ｜ 正经点赞（清远）媒体科技有限公司 · 数字内容创作<br>北江人工智能产教融合研究院 · AI 产教融合 ｜ 光年制造工作室 · 创意设计 ｜ 彗星互娱工作室 · 创意文娱设计<br><b>2026-08-01 揭牌当日签约入驻。</b>\"}'),(23,'join-form','join','📝 入驻申请',NULL,NULL,NULL,NULL,3,'0',1,'admin','2026-08-26 08:15:53','form',NULL),(24,'join-contact','join','📮 咨询信息',NULL,NULL,NULL,NULL,4,'0',1,'admin','2026-08-26 08:15:53','list','{\"items\": [{\"desc\": \"0763-3391888\", \"title\": \"咨询电话\"}, {\"desc\": \"清远国家高新技术产业开发区天安智谷产业园 B6 栋、T1 栋 1105\", \"title\": \"社区地址\"}]}'),(25,'talent-schools','talent','🎓 高校合作 · 校外实践教学基地',NULL,NULL,NULL,NULL,1,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"🏫\", \"text\": \"共建校外实践教学基地、AI 实训基地，联合培养应用型 AI 人才\", \"title\": \"广东财贸职业学院\"}, {\"icon\": \"🏫\", \"text\": \"共建校外实践教学基地、AI 实训基地，联合培养应用型 AI 人才\", \"title\": \"清远职业技术学院\"}, {\"icon\": \"🏫\", \"text\": \"共建校外实践教学基地、AI 实训基地，联合培养应用型 AI 人才\", \"title\": \"广东岭南职业技术学院\"}]}'),(26,'talent-training','talent','🧑‍🏫 培训体系',NULL,NULL,NULL,NULL,2,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 2, \"cards\": [{\"icon\": \"🎬\", \"text\": \"AI 短视频创作、智能内容生产技能培训常态化开展，零基础也能快速上手。\", \"title\": \"常态化 AI 技能培训\"}, {\"icon\": \"🚀\", \"text\": \"已举办多期，手把手教你从 0 到 1 开一家\\\"一人公司\\\"。\", \"title\": \"OPC 创客训练营\"}, {\"icon\": \"🧑‍🎓\", \"text\": \"面向本地高校毕业生，衔接就业与创业，学完即可接单。\", \"title\": \"高校毕业生专属实训营\"}, {\"icon\": \"🌱\", \"text\": \"清远籍大学生可免费参加 OPC 创业训练营，回家乡也能创未来。\", \"title\": \"清远籍大学生免费训练营\"}]}'),(27,'talent-tools','talent','🛠️ 教学工具',NULL,NULL,NULL,NULL,3,'0',1,'admin','2026-08-26 08:15:53','text','{\"text\": \"依托塔链人工智能科技（广州）有限公司研发迭代 <b>\\\"无限画布\\\"</b> 与 <b>\\\"AgentSkill\\\"</b> 教学工具，让 AI 技能学习更直观、上手更快。\"}'),(28,'talent-ecosystem','talent','🌐 人才生态',NULL,NULL,NULL,NULL,4,'0',1,'admin','2026-08-26 08:15:53','stats','{\"text\": \"联动<b>\\\"百万英才汇南粤\\\"</b>、<b>\\\"青雁归清\\\"</b>计划，让清远籍人才回得来、留得住、创得成。\", \"items\": [{\"label\": \"省职教城高校数量\", \"value\": \"10 所\"}, {\"label\": \"省职教城师生人才储备\", \"value\": \"14 万+\"}]}'),(29,'talent-cta-banner','talent','报名训练营，解锁 AI 新技能',NULL,NULL,NULL,NULL,5,'0',1,'admin','2026-08-26 08:15:53','cta','{\"text\": \"OPC 创客训练营 / 毕业生 AI 实训营正在招募中 ｜ 咨询电话：0763-3391888\", \"btnLink\": \"home.html#contact\", \"btnText\": \"前往首页报名\"}'),(30,'industry-stats','industry','📊 行业背景数据',NULL,NULL,NULL,NULL,1,'0',1,'admin','2026-08-26 08:15:53','stats','{\"items\": [{\"label\": \"2025 年国内 AI 视频市场规模突破\", \"value\": \"1200 亿+\"}, {\"label\": \"预计 2030 年市场规模达\", \"value\": \"5800 亿\"}, {\"label\": \"2026 年 Q1 上新微短剧 AI 制作占比\", \"value\": \"95%+\"}, {\"label\": \"2026 年 AI 短剧市场规模预计冲击\", \"value\": \"400 亿\"}]}'),(31,'industry-tracks','industry','🎯 三大赛道',NULL,NULL,NULL,NULL,2,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"🎬\", \"text\": \"聚焦 AI 微短剧、超级数字人、AIGC 内容创作。全国首部 AIGC 黄梅戏微短剧《打猪草》已采用仿真数字人与动作捕捉技术，为内容创作注入 AI 新表达。<ul><li>AI 微短剧</li><li>超级数字人</li><li>AIGC 内容创作</li></ul>\", \"title\": \"AI 内容创作\"}, {\"icon\": \"🤖\", \"text\": \"聚焦本土自研 AI 获客系统、GEO（生成式引擎优化）与 AI 应用开发，让 AI 能力真正落地为获客与增长工具。<ul><li>本土自研 AI 获客系统</li><li>GEO（生成式引擎优化）</li><li>AI 应用开发</li></ul>\", \"title\": \"AI 技术应用\"}, {\"icon\": \"🕶️\", \"text\": \"覆盖 AI 眼镜、AI 手机、AI 工牌、AI 玩具、AI 陪伴设备、AI 外骨骼辅助装置，以及多个 AI 场景训练场，构建硬件 + 场景的完整生态链。<ul><li>AI 眼镜 / AI 手机 / AI 工牌 / AI 玩具</li><li>AI 陪伴设备 / AI 外骨骼辅助装置</li><li>AI 具身智能训练场</li><li>AI 工业场景训练场 / AI 生活场景训练场</li></ul>\", \"title\": \"AI 硬件与场景生态链\"}]}'),(32,'industry-companies','industry','🏢 首批入驻企业（2026-08-01 揭牌签约）',NULL,NULL,NULL,NULL,3,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"🔬\", \"text\": \"AI 技术研发 —— 研发迭代\\\"无限画布\\\"\\\"AgentSkill\\\"教学工具\", \"title\": \"塔链人工智能科技（广州）有限公司\"}, {\"icon\": \"🧠\", \"text\": \"AI 技术研发\", \"title\": \"南京世东智脑人工智能有限公司\"}, {\"icon\": \"🎬\", \"text\": \"数字内容创作\", \"title\": \"正经点赞（清远）媒体科技有限公司\"}, {\"icon\": \"🎓\", \"text\": \"AI 产教融合\", \"title\": \"北江人工智能产教融合研究院\"}, {\"icon\": \"🎨\", \"text\": \"创意设计\", \"title\": \"光年制造工作室\"}, {\"icon\": \"🎮\", \"text\": \"创意文娱设计\", \"title\": \"彗星互娱工作室\"}]}'),(33,'industry-merge','industry','🔗 产业融合',NULL,NULL,NULL,NULL,4,'0',1,'admin','2026-08-26 08:15:53','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"🏞️\", \"text\": \"用 AIGC 短剧、数字人讲解与文创内容，为清远文旅资源注入 AI 新表达。\", \"title\": \"AI + 文旅\"}, {\"icon\": \"🏭\", \"text\": \"AI 视觉检测、智能排产与工业场景训练，助力本地制造业智能化升级。\", \"title\": \"AI + 制造\"}, {\"icon\": \"🛍️\", \"text\": \"数字人直播、智能客服与个性化推荐，重塑本地生活与现代服务体验。\", \"title\": \"AI + 现代服务业\"}]}'),(35,'home-hero','home','首页首屏（轮播+文案）',NULL,NULL,NULL,NULL,1,'0',3,'admin','2026-08-27 08:14:26','hero','{\"title\": \"清远市首个人工智能 OPC 生态社区\", \"content\": \"数智游民创新工场由清城区政府与清远星链科技合作共建，以\\\"国企引领、民企赋能\\\"模式运营，从签约到揭牌仅用 21 天。社区为 AI 时代的超级个体与一人公司提供\\\"拎脑入驻\\\"的完整生态：免费工位与注册代办降低启动门槛，70B 大模型一体机与算力券让 AI 生产力触手可及，文创订单对接与创客基金让作品直接变现，省职教城 14 万人才与高校实践基地持续注入新鲜血液。\", \"subtitle\": \"一个人 + AI，把想法变成事业——免费工位 · 算力加持 · 订单牵引，拎脑入驻清远 AI 生态社区\"}'),(36,'home-empower','home','三大赋能体系',NULL,NULL,NULL,NULL,3,'0',3,'admin','2026-08-27 08:14:26','cards','{\"cols\": 3, \"cards\": [{\"icon\": \"💻\", \"text\": \"与阿里巴巴深度合作，核心 AI 生态体系清城区私有化部署；智谱等开源大模型开发支撑平台随时调用；SD-WAN 网络直连国内外优质大模型。入驻即可申请试用 70B 以内大模型一体机，并享省级算力券补贴——让每个人的 AI 生产力都用得起。\", \"title\": \"算力与技术支持\"}, {\"icon\": \"🏦\", \"text\": \"创客特色贷款财政贴息、数字游民最高 2 万元资金奖励、80 万元担保贷款、3 万元运营激励、市级孵化基地最高 300㎡ 三年免费；发改、工信、人社等多部门一站式政策对接，帮你把每一分政策红利都落进口袋。\", \"title\": \"政策与金融服务\"}, {\"icon\": \"📦\", \"text\": \"全面梳理文旅推广、政务科普、城市形象等文创订单需求，联动星火深智等 AI 头部企业对接全国稳定内容订单；2026 首届 OPC 创客短视频创作大赛与创客基金同步就位，以订单和赛事牵引产业集聚——入驻即有活干。\", \"title\": \"订单与市场牵引\"}]}'),(37,'home-companies','home','入驻企业 & AI+ 融合',NULL,NULL,NULL,NULL,4,'0',3,'admin','2026-08-27 08:14:26','tags','{\"groups\": [{\"tags\": [\"塔链人工智能科技\", \"南京世东智脑\", \"正经点赞（清远）媒体科技\", \"北江人工智能产教融合研究院\", \"光年制造工作室\", \"彗星互娱工作室\"], \"title\": \"首批入驻企业\"}, {\"tags\": [\"AI + 文旅\", \"AI + 制造\", \"AI + 现代服务业\"], \"title\": \"AI + 产业融合\"}, {\"tags\": [\"清城区政府\", \"清远星链科技\", \"顺拓集团\", \"星拓公司\"], \"title\": \"合作共建方\"}]}'),(38,'home-news','home','新闻动态',NULL,NULL,NULL,NULL,6,'0',3,'admin','2026-08-27 08:14:26','news','{\"count\": 6}'),(39,'home-contact','home','发展历程 & 联系我们',NULL,NULL,NULL,NULL,7,'0',3,'admin','2026-08-27 08:14:26','contact','{\"items\": [{\"date\": \"2026-04-29\", \"desc\": \"数智游民创新工场（清远）科技有限公司注册成立（注册资本 100 万元）。\", \"title\": \"运营公司成立\"}, {\"date\": \"2026-07-11\", \"desc\": \"清城区政府与清远市星链科技有限公司签署协议，共建人工智能 OPC 生态社区。\", \"title\": \"签署合作框架协议\"}, {\"date\": \"2026-08-01\", \"desc\": \"揭牌当天 6 家企业签约入驻、3 所本地高校共建实践基地——从签约到揭牌仅 21 天，被誉为“清城速度”。\", \"title\": \"正式揭牌运营\"}]}'),(40,'home-cta','home','入驻 CTA 横幅',NULL,NULL,NULL,NULL,8,'0',3,'admin','2026-08-27 08:14:26','cta','{\"text\": \"免费工位 · 政策赋能 · 订单对接 · 算力加持 ｜ 入驻咨询：0763-3391888\", \"title\": \"一个人 + AI，开启你的 OPC 事业\", \"btnLink\": \"join.html\", \"btnText\": \"立即入驻\"}');
